@_mutmut_mutated(mutants_x__generate_id__mutmut)
def _generate_id(ticker: str, timestamp: float) -> str:
    """Generate a unique ID for a market regime."""
    key = f"{ticker}_{timestamp}"
    return hashlib.md5(key.encode()).hexdigest()


